"""Regenerate src/game/index.ts: imports every ported module under src/game (except helpers)."""
import os
root = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "src", "game")
# Modules kept out of the build on purpose (reason shown in the generated file).
DISABLED = {
}
mods = []
for d, _, files in os.walk(root):
    for f in files:
        if not f.endswith(".ts") or f in ("index.ts", "machine.ts"):
            continue
        rel = os.path.relpath(os.path.join(d, f), root).replace(os.sep, "/")
        if rel.startswith("common/"):
            continue
        mods.append("./" + rel[:-3])
with open(os.path.join(root, "index.ts"), "w") as fh:
    fh.write("// Generated by tools/gen_index.py: imports every ported module so its routines get registered.\n")
    for m in sorted(mods):
        if m in DISABLED:
            fh.write(f'// import "{m}"; // {DISABLED[m]}\n')
        else:
            fh.write(f'import "{m}";\n')
print(len(mods), "modules")
